<?php namespace App\Services; use App\Models\ProductVariant; use App\Repositories\ProductVariant\ProductVariantRepositoryInterface; use Illuminate\Support\Str; class ProductVariantService {public function __construct(private ProductVariantRepositoryInterface $repo){} public function list(array $f){return $this->repo->paginate($f);} public function create(array $d):ProductVariant{$d['barcode']=$d['barcode']?:'NM'.now()->format('ymd').strtoupper(Str::random(8));return $this->repo->create($d);} public function update(ProductVariant $v,array $d):ProductVariant{$d['barcode']=$d['barcode']?:$v->barcode;return $this->repo->update($v,$d);} public function delete(ProductVariant $v):void{$this->repo->delete($v);}}